        <div class="w-full flex-1 flex px-9 sm:px-16 mlg:w-auto mlg:px-0">
          <!-- tabs... -->
          <template v-for="n in tabRoutes">
            <li :class="['relative flex-1', [n === active ? 'text-pen' : 'text-pencil-3h']]" :style="{zIndex: n === active ? 6 : 4 - layering.indexOf(n)}">
              <router-link :to="`/${n}`" class="tab-link">
                <FolderTab :isActive="n === active">
                  <div class="tab-link-text rounded-xl relative z-40">
                    <div class="hidden md:block">{{ n }}</div>
                    <SvgStars v-if="n === 'mint'" class="md:hidden h-12" stroke-width="6" />
                    <!-- <SvgSnake v-if="n === 'nfts'" class="md:hidden h-12" stroke-width="9" /> -->
                    <SvgQuestionMark v-if="n === 'faq'" class="md:hidden h-12" stroke-width="7" />
                  </div>
                </FolderTab>
              </router-link>
            </li>
          </template>
        </div>
        
      </ul>
    </header>
  
    <main class="flex-1 flex border-stroke rounded-stroke3x">
      <router-view v-slot="{ Component, route }">
        <component :is="Component" />
      </router-view>
    </main>
  </div>
  
  <!-- mint listener -->
  <!-- <contract-listener v-if="$store.state.mintCount < 545" @update="$store.dispatch('getMintCount', {})" /> -->
</template>
  
<script setup>
  // import ContractListener from '@/components/ContractListener.vue'
  import FolderTab from '@/components/FolderTab.vue'
  import SvgLogo from '../components/SvgLogo.vue';
  import { ref, watch } from 'vue';
  import { useRoute } from 'vue-router'
  import SvgStars from '../components/SvgStars.vue'
  // import SvgSnake from '../components/SvgSnake.vue'
  import SvgQuestionMark from '../components/SvgQuestionMark.vue'
  
  const route = useRoute()
  const tabRoutes = ['mint', 'nfts', 'faq']
  const active = ref(tabRoutes.find(rt => rt === route.name?.split('-')[0]))
  const layering = ref(tabRoutes.slice(0))

  // change tab layering on rt change
  watch(route, ({name}) => {
    const activeTab = tabRoutes.find(rt => rt === name.split('-')[0])
    if (activeTab) {
      const index = layering.value.indexOf(activeTab)
      layering.value.unshift(layering.value.splice(index, 1)[0])
      active.value = activeTab
    } else {
      active.value = undefined
    }
  })
</script>
  
<script>
export default {
    metaInfo() {
        return this.$store.getters.meta({});
    },
    components: { FolderTab, FolderTab, FolderTab, FolderTab, SvgLogo }
}
</script>

